import sys

def main():
    lines = sys.stdin.read().splitlines()
    idx = 0
    if idx >= len(lines):
        return

    n = int(lines[idx].strip())
    idx += 1

    categories = []

    for _ in range(n):
        parts = lines[idx].strip().split()
        idx += 1
        cat_name = parts[0]
        w = int(parts[1])
        words = parts[2:2+w]
        categories.append((cat_name, set(words)))

    statement_words = []
    while idx < len(lines):
        line_words = lines[idx].strip().split()
        statement_words.extend(line_words)
        idx += 1

    counts = {}
    for cat_name, cat_words in categories:
        counts[cat_name] = 0

    for word in statement_words:
        for cat_name, cat_words in categories:
            if word in cat_words:
                counts[cat_name] += 1

    if not counts:
        return

    max_count = max(counts.values())
    suggested = [name for name, count in counts.items() if count == max_count]
    suggested.sort()

    for name in suggested:
        print(name)

if __name__ == "__main__":
    main()
